var KANJI=[['日','にち'],['月','げつ'],['火','か'],['水','すい'],['木','もく'],['金','きん'],['土','ど'],['人','じん'],['口','こう'],['目','もく'],['手','しゅ'],['足','そく'],['山','さん'],['川','せん'],['田','でん'],['雨','う'],['電','でん'],['車','しゃ'],['学','がく'],['生','せい'],['先','せん'],['本','ほん'],['字','じ'],['時','じ'],['間','かん'],['行','こう'],['来','らい'],['出','しゅつ'],['入','にゅう'],['上','じょう'],['下','か']];
function quiz(rng, pool){
  pool=pool||KANJI; var q=pool[Math.floor(rng()*pool.length)];
  var opts=[q[1]]; while(opts.length<4){ var c=pool[Math.floor(rng()*pool.length)][1]; if(opts.indexOf(c)<0) opts.push(c); }
  for(var i=opts.length-1;i>0;i--){ var j=Math.floor(rng()*(i+1)); var t=opts[i];opts[i]=opts[j];opts[j]=t; }
  return {kanji:q[0], answer:q[1], choices:opts};
}
function check(q, pick){ return pick===q.answer; }
var EXPORTS={KANJI:KANJI,quiz:quiz,check:check};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.KanjiForgePure = EXPORTS; }
